// The editing.ajenepinnock.com templates, rebuilt from a frame-by-frame read of the 31 public sample videos
// (15 s each, same script: hook → "most people post every day and still get no clients" → "the problem isn't your
// content, it's your system" → step one/two/three → "do that for thirty days and watch what happens").
// Every template is one 15 s scene: layered components switched on/off on a GSAP timeline, one-word captions at the
// chest with the keyword in orange serif italic, and (where the sample does it) the camera moving into a dark panel
// at the bottom. Colours: dark room, cream type, clay orange; UI panels rgba(27,26,24,.92) with a hairline border.
import { SKILLS, CAPTIONS, ELEMENTS, PRESETS, COLOURS } from "./looks.mjs";
import { holeVars } from "./layers.mjs";

SKILLS["ajene-templates"] = { name: "Templates Ajene (nossa versão)", cmd: "/look-builder", note: "Cenas de 15 s: gancho, legendas palavra a palavra, painéis de UI, grade de 30 dias, contadores, tier list, recortes." };

const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const sans = (S) => S.font.body || "'Instrument Sans','Inter',system-ui,sans-serif";
const serif = (S) => S.font.serif || "'EdSerif','Instrument Serif',Georgia,serif";
const CLAY = "#d97757", CLAY2 = "#e8916f", CREAM = "#f0eee6", PANEL = "rgba(27,26,24,.92)", LINE = "#45423b", GREEN = "#4cc38a";
const words = (S) => S.text.words || [];
const kw = (S) => String(S.text.keyword || "").toLowerCase();
const full = (S, inner) => `<div class="ov el aj" data-ht="${S.headTop}" data-ct="${S.capTop}" style="left:0;top:0;width:${S.W}px;height:${S.H}px;font-family:${sans(S)};color:${CREAM}">${inner}</div>`;
const L = (cls, style, inner = "") => `<div class="${cls}${/--hy:/.test(style) ? " back hole" : ""}" style="position:absolute;opacity:0;${style}">${inner}</div>`;
const abs = (style, inner = "", cls = "") => `<div class="${cls}" style="position:absolute;${style}">${inner}</div>`;
const lines = (x, y, ws, gap = 22, c = "rgba(240,238,230,.35)", h = 10) => ws.map((w, i) => `<i style="position:absolute;left:${x}px;top:${y + i * gap}px;width:${w}px;height:${h}px;border-radius:5px;background:${c}"></i>`).join("");
const dot = (x, y, r, c) => `<i style="position:absolute;left:${x - r}px;top:${y - r}px;width:${r * 2}px;height:${r * 2}px;border-radius:50%;background:${c}"></i>`;

// full-frame backdrops get a soft hole around the presenter: the preview has no person matte (the edit skill cuts the real one)
const hole = (S) => holeVars(S);
// ---------------------------------------------------------------- components (HTML only; timing lives in the scene)
const panel = (x, y, w, h, inner = "", extra = "") => abs(`left:${x}px;top:${y}px;width:${w}px;height:${h}px;background:${PANEL};border:1.5px solid ${LINE};border-radius:28px;box-shadow:0 30px 60px rgba(0,0,0,.45);${extra}`, inner);
const glass = (x, y, w, h, inner = "", extra = "") => abs(`left:${x}px;top:${y}px;width:${w}px;height:${h}px;background:rgba(240,238,230,.10);border:1.5px solid rgba(240,238,230,.28);border-radius:28px;backdrop-filter:blur(14px);box-shadow:0 20px 50px rgba(0,0,0,.35);${extra}`, inner);
const cream = (x, y, w, h, inner = "", extra = "") => abs(`left:${x}px;top:${y}px;width:${w}px;height:${h}px;background:${CREAM};border-radius:18px;box-shadow:0 24px 60px rgba(0,0,0,.45);color:#1b1a18;${extra}`, inner);
const tag = (S, x, y, t, c = CLAY) => abs(`left:${x}px;top:${y}px;font:600 20px/1 ${sans(S)};letter-spacing:.12em;text-transform:uppercase;color:${c}`, esc(t));
const eyebrow = (S, t) => `<div style="font:600 22px/1 ${sans(S)};letter-spacing:.16em;text-transform:uppercase;color:rgba(240,238,230,.55)">${esc(t)}</div>`;
// two-line hook in white boxes, black text (Business/Personal/Cut-outs/TikTok/Yap)
const hookBoxes = (S, l1, l2, sub, y) => abs(`left:0;width:${S.W}px;top:${y}px;text-align:center;line-height:1.45`, `<span style="display:inline-block;background:#fff;color:#111;padding:2px 20px;font:800 56px ${sans(S)}">${esc(l1)}</span><br><span style="display:inline-block;background:#fff;color:#111;padding:2px 20px;font:800 56px ${sans(S)};margin-top:6px">${esc(l2)}</span>${sub ? `<div style="font:600 26px ${sans(S)};color:#fff;text-shadow:0 2px 10px #000;margin-top:14px">${esc(sub)}</div>` : ""}`);
// "Posting Every Day, / Still *No Clients*" sans + orange serif italic underlined
const hookSerif = (S, l1, l2a, l2b, y, size = 52) => abs(`left:0;width:${S.W}px;top:${y}px;text-align:center;color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.6)`, `<div style="font:700 ${size}px/1.15 ${sans(S)}">${esc(l1)}</div><div style="font:700 ${size}px/1.15 ${sans(S)}">${esc(l2a)} <i style="font:italic 400 ${size * 1.15}px ${serif(S)};color:${CLAY};border-bottom:3px solid ${CLAY}">${esc(l2b)}</i></div>`);
// notification card (@yourhandle · "66 new likes on your post")
const notif = (S, x, y, w, user, text, i = 0) => abs(`left:${x}px;top:${y}px;width:${w}px;height:92px;background:${PANEL};border:1.5px solid ${LINE};border-radius:22px;box-shadow:0 14px 30px rgba(0,0,0,.4)`, `${dot(44, 46, 20, "#6f6c64")}<div style="position:absolute;left:78px;top:18px;font:700 22px ${sans(S)};color:${CREAM}">${esc(user)}</div><div style="position:absolute;left:78px;top:50px;font:500 20px ${sans(S)};color:rgba(240,238,230,.65)">${esc(text)}</div><div style="position:absolute;right:22px;top:18px;font:500 18px ${sans(S)};color:rgba(240,238,230,.4)">${i + 1} min</div>`, "nf");
// step pill ("Hook" with icon, glowing when active)
const pill = (S, x, y, w, n, label, on = true) => abs(`left:${x}px;top:${y}px;width:${w}px;height:72px;border-radius:999px;background:${on ? "rgba(217,119,87,.22)" : PANEL};border:1.5px solid ${on ? CLAY : LINE};box-shadow:${on ? `0 0 30px rgba(217,119,87,.35)` : "none"}`, `<span style="position:absolute;left:24px;top:18px;width:36px;height:36px;border-radius:10px;background:${on ? CLAY : "#3a3833"};color:#1b1a18;display:grid;place-items:center;font:800 18px ${sans(S)}">${n}</span><span style="position:absolute;left:76px;top:20px;font:700 28px ${sans(S)};color:${CREAM}">${esc(label)}</span><span style="position:absolute;right:26px;top:24px;font:500 18px ${sans(S)};color:rgba(240,238,230,.45)">0${n}</span>`, "pl");
// 30-day grid (cells light up)
const grid30 = (S, x, y, w, cell = 52, gap = 10, cols = 10, rows = 3, color = CLAY) => abs(`left:${x}px;top:${y}px;width:${w}px`, Array.from({ length: cols * rows }).map((_, i) => `<i class="gc" data-i="${i}" style="position:absolute;left:${(i % cols) * (cell + gap)}px;top:${Math.floor(i / cols) * (cell + gap)}px;width:${cell}px;height:${cell}px;border-radius:10px;background:#2a2724;border:1px solid ${LINE};--on:${color}"></i>`).join(""), "g30");
// counter card ("New clients" · 0 → 12)
const counter = (S, x, y, w, h, label, cls = "ct", color = CREAM, start = "0") => abs(`left:${x}px;top:${y}px;width:${w}px;height:${h}px;background:${PANEL};border:1.5px solid ${LINE};border-radius:24px`, `<div style="position:absolute;left:28px;top:22px;font:500 20px ${sans(S)};color:rgba(240,238,230,.55)">${esc(label)}</div><div class="${cls}" style="position:absolute;left:28px;bottom:18px;font:800 76px/1 ${sans(S)};color:${color};letter-spacing:-.03em">${start}</div>`);
// growth chart that draws in
const chart = (x, y, w, h, color = CLAY) => `<svg class="ch" viewBox="0 0 100 50" preserveAspectRatio="none" style="position:absolute;left:${x}px;top:${y}px;width:${w}px;height:${h}px;overflow:visible"><path class="cp" d="M2 46 C 20 45, 35 40, 50 32 S 80 12, 98 4" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" vector-effect="non-scaling-stroke"/><circle class="cd" cx="98" cy="4" r="2.2" fill="#fff"/></svg>`;
// google-doc style cream card ("30-Day Content Plan")
const doc = (S, x, y, w, h, title, body = []) => cream(x, y, w, h, `<div style="position:absolute;left:0;right:0;top:0;height:54px;border-bottom:1px solid #d9d2c6;border-radius:18px 18px 0 0;background:#fff">${dot(28, 27, 10, "#4285f4")}<span style="position:absolute;left:52px;top:16px;font:600 20px ${sans(S)};color:#333">${esc(title)}</span><span style="position:absolute;right:16px;top:12px;background:#1a73e8;color:#fff;border-radius:8px;padding:5px 14px;font:600 16px ${sans(S)}">Share</span></div><div style="position:absolute;left:30px;top:80px;font:800 34px ${sans(S)};color:#1b1a18">${esc(title)}</div>${body.map((b, i) => `<div class="dl" style="position:absolute;left:30px;top:${140 + i * 40}px;font:600 22px ${sans(S)};color:#333">${esc(b)}</div>`).join("")}${lines(30, 150 + body.length * 40, [w - 80, w - 120, w - 160, w - 100], 26, "#d9d2c6", 9)}`);
// reel covers band (row of dark cards with ▶)
const covers = (S, y, n = 6, w = 150, h = 240) => abs(`left:0;top:${y}px;width:${S.W}px;height:${h}px;overflow:hidden`, Array.from({ length: n }).map((_, i) => `<div style="position:absolute;left:${-60 + i * (w + 18)}px;top:0;width:${w}px;height:${h}px;border-radius:18px;background:linear-gradient(160deg,#4a4740,#23221e);border:1px solid ${LINE}"><span style="position:absolute;left:10px;top:10px;font:600 13px ${sans(S)};letter-spacing:.1em;color:rgba(240,238,230,.5)">REEL COVER</span>${dot(w / 2, h / 2, 18, "rgba(240,238,230,.85)")}</div>`).join(""), "cv");
// presenter panel at the bottom (the camera flies into it); glow behind
const bottomPanel = (S) => abs(`left:${S.W * 0.04}px;top:${S.H * 0.63}px;width:${S.W * 0.92}px;height:${S.H * 0.34}px;border-radius:30px;border:1.5px solid ${LINE};box-shadow:0 0 80px rgba(217,119,87,.18)`, `<span style="position:absolute;left:20px;top:14px;font:600 14px ${sans(S)};letter-spacing:.12em;color:rgba(240,238,230,.4)">YOUR VIDEO</span>`, "bp");
const glow = (S, x, y, r, c = "rgba(217,119,87,.25)") => abs(`left:${x - r}px;top:${y - r}px;width:${r * 2}px;height:${r * 2}px;border-radius:50%;background:radial-gradient(circle,${c},transparent 65%)`);

// framing read back from the element root (anims are serialised for the real test, so no closures over state)
const S0 = (el) => ({ W: parseFloat(el.style.width) || 1080, H: parseFloat(el.style.height) || 1920, headTop: +el.dataset.ht || 620, capTop: +el.dataset.ct || 1300 });
// camera moves (cam = #cam of the stage; null in cards without camera)
// the presenter flies into the wide bottom panel: scaled to the panel width, re-centred on the face and clipped to the panel
const camToBottom = (tl, cam, el, at) => { if (!cam) return; const { W, H, headTop } = S0(el); const x0 = W * 0.04, w = W * 0.92, y0 = H * 0.63, h = H * 0.34, s = w / W, faceC = headTop + 230; const lh = h / s, lt = Math.max(0, Math.min(H - lh, faceC - lh * 0.5)); const ty = (y0 + h / 2) - (H / 2 + (lt + lh / 2 - H / 2) * s); tl.to(cam, { scale: s, y: ty, clipPath: `inset(${lt}px 0px ${H - lt - lh}px 0px round ${30 / s}px)`, duration: 0.6, ease: "power3.inOut" }, at); const c = capsOf(el); if (c) tl.to(c, { y: (y0 + h - 170) - (S0(el).capTop - 30), duration: 0.6, ease: "power3.inOut" }, at); };
const capsOf = (el) => { const w = el.closest(".lb-back,.lb-front"); const sel = w ? (w.classList.contains("lb-back") ? ".lb-back .caps" : ".lb-front .caps") : ".caps"; return (el.closest("[data-composition-id]") || (w && w.parentElement) || el.parentElement || document).querySelector(sel); };
const camBack = (tl, cam, el, at) => { if (!cam) return; tl.to(cam, { scale: 1, y: 0, clipPath: "inset(0px 0px 0px 0px round 0px)", duration: 0.5, ease: "power3.inOut" }, at); const c = capsOf(el); if (c) tl.to(c, { y: 0, duration: 0.5, ease: "power3.inOut" }, at); };
// timeline helpers: show a layer between t0 and t1 with a soft rise
const show = (tl, el, sel, t0, t1, y = 24) => { const n = el.querySelector(sel); if (!n) return; tl.fromTo(n, { opacity: 0, y }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out" }, t0); if (t1 != null) tl.to(n, { opacity: 0, duration: 0.3 }, t1); };
const seq = (tl, el, sel, t0, step = 0.45) => el.querySelectorAll(sel).forEach((n, i) => tl.fromTo(n, { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 0.35, ease: "power3.out" }, t0 + i * step));
const fillGrid = (tl, el, t0, dur = 1.6, color) => { const cells = [...el.querySelectorAll(".gc")]; cells.forEach((c, i) => tl.to(c, { backgroundColor: color || getComputedStyle(c).getPropertyValue("--on").trim() || CLAY, borderColor: "transparent", duration: 0.15 }, t0 + (i / cells.length) * dur)); };
const count = (tl, el, sel, to, t0, dur = 1.2, prefix = "") => { const n = el.querySelector(sel); if (!n) return; const o = { v: 0 }; tl.to(o, { v: to, duration: dur, ease: "power2.out", onUpdate: () => (n.textContent = prefix + Math.round(o.v)) }, t0); };
const drawChart = (tl, el, t0) => el.querySelectorAll(".cp").forEach((p) => { const len = p.getTotalLength(); p.style.strokeDasharray = len; tl.fromTo(p, { strokeDashoffset: len }, { strokeDashoffset: 0, duration: 1.2, ease: "power2.inOut" }, t0); });

// ---------------------------------------------------------------- captions in his style (one word, keyword orange serif italic)
CAPTIONS.push({ id: "aj-word", name: "Palavra a palavra (Ajene)", desc: "Uma palavra por vez no peito, branca; a palavra-chave em serif itálico laranja", skills: ["ajene-templates"], mode: "word",
  render: (S) => `<div class="ov caps" style="left:0;top:${S.capTop - 30}px;width:${S.W}px;height:120px">${words(S).map((w, i) => { const em = w.toLowerCase() === kw(S); return `<span class="w" data-i="${i}" style="position:absolute;left:0;top:0;width:${S.W}px;text-align:center;opacity:0;${em ? `font:italic 400 92px/120px ${serif(S)};color:${CLAY}` : `font:600 58px/120px ${sans(S)};color:#fff`};text-shadow:0 2px 12px rgba(0,0,0,.6)">${esc(w)}</span>`; }).join("")}</div>` });
CAPTIONS.push({ id: "aj-phrase", name: "Frase curta (Ajene)", desc: "Frases de 3–4 palavras, brancas, pequenas, com sombra (cut-outs, TikTok)", skills: ["ajene-templates"], mode: "phrase",
  render: (S) => { const ch = []; let cur = []; for (const w of words(S)) { cur.push(w); if (cur.length >= 4) { ch.push(cur.join(" ")); cur = []; } } if (cur.length) ch.push(cur.join(" ")); return `<div class="ov caps" style="left:0;top:${S.capTop}px;width:${S.W}px;text-align:center">${ch.map((c, i) => `<span class="w" data-i="${i}" style="position:absolute;left:0;right:0;top:0;opacity:0;font:600 38px ${sans(S)};color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.7)">${esc(c)}</span>`).join("")}</div>`; } });
CAPTIONS.push({ id: "aj-stacked", name: "Frase que cresce (Ajene)", desc: "A frase vai acumulando palavra a palavra; a palavra-chave entra em serif itálico laranja grande", skills: ["ajene-templates"], mode: "phrase",
  render: (S) => { const ws = words(S); return `<div class="ov caps" style="left:${S.W * 0.1}px;top:${S.capTop - 20}px;width:${S.W * 0.8}px;text-align:center">${ws.map((_, i) => `<span class="w" data-i="${i}" style="position:absolute;left:0;right:0;top:0;opacity:0;font:600 34px/1.3 ${sans(S)};color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.7)">${ws.slice(0, i + 1).map((w) => (w.toLowerCase() === kw(S) ? `<i style="display:block;font:italic 400 110px/1 ${serif(S)};color:${CLAY}">${esc(w)}</i>` : esc(w))).join(" ")}</span>`).join("")}</div>`; } });

CAPTIONS.push({ id: "ear-to-ear", name: "Orelha a orelha (16:9)", desc: "Palavras dos dois lados da cabeça, na altura dos olhos, alternando esquerda e direita", skills: ["ajene-templates"], mode: "word",
  render: (S) => { const ey = Math.max(60, S.headTop + 110); return `<div class="ov caps" style="left:0;top:${ey}px;width:${S.W}px;height:120px">${words(S).map((w, i) => { const em = w.toLowerCase() === kw(S), left = i % 2 === 0; return `<span class="w" data-i="${i}" style="position:absolute;top:0;${left ? `right:${S.W / 2 + 190}px;text-align:right` : `left:${S.W / 2 + 190}px;text-align:left`};width:${S.W / 2 - 240}px;opacity:0;${em ? `font:italic 400 ${S.landscape ? 72 : 60}px/120px ${serif(S)};color:${CLAY}` : `font:600 ${S.landscape ? 48 : 40}px/120px ${sans(S)};color:#fff`};text-shadow:0 2px 12px rgba(0,0,0,.6)">${esc(w)}</span>`; }).join("")}</div>`; } });

// Helpers the scene anims use, as source, so testbuild.mjs can serialise an anim and still run it inside the HyperFrames page.
export const AJ_RUNTIME = [
  `const CLAY = ${JSON.stringify(CLAY)}, CLAY2 = ${JSON.stringify(CLAY2)}, CREAM = ${JSON.stringify(CREAM)}, PANEL = ${JSON.stringify(PANEL)}, LINE = ${JSON.stringify(LINE)}, GREEN = ${JSON.stringify(GREEN)};`,
  `const S0 = ${S0.toString()};`, `const camToBottom = ${camToBottom.toString()};`, `const camBack = ${camBack.toString()};`, `const capsOf = ${capsOf.toString()};`,
  `const show = ${show.toString()};`, `const seq = ${seq.toString()};`, `const fillGrid = ${fillGrid.toString()};`, `const count = ${count.toString()};`, `const drawChart = ${drawChart.toString()};`,
].join("\n");

// ---------------------------------------------------------------- scene builder
const PT = { most: "Most people", post: "post every day", still: "and still get", nocl: "no clients.", problem: "The problem isn't", content: "your content.", system: "It's your system.", s1: "Step one: hook.", s2: "Step two: story.", s3: "Step three: offer.", dothat: "Do that for", thirty: "thirty days,", watch: "and watch", happens: "what happens." };
function scene(id, name, desc, build, opts = {}) {
  ELEMENTS.push({ id: `aj:${id}`, name, desc, skills: ["ajene-templates"], camera: !!opts.camera, dur: 15, scene: true,
    render: (S) => full(S, build.render(S)), anim: build.anim });
  PRESETS.push({ id: `tpl-${id}`, name, desc, skill: "ajene-templates", picks: { colours: "ajene", fonts: "jakarta-inter", hook: "none", captions: opts.captions || "aj-word", elements: [`aj:${id}`], motion: [] } });
}
const h2 = (S) => [String(S.text.hook1 || "Posting every day"), String(S.text.hook2 || "but still no clients?")];
const notifs = (S, x, y, w) => [["@yourhandle", "66 new likes on your post"], ["@yourhandle", "Your reel reached 12,400 views"], ["@yourhandle", "1 new client enquiry this week"]].map(([u, t], i) => notif(S, x, y + i * 104, w, u, t, i)).join("");
const stepPills = (S, x, y, w) => [["Hook", 1], ["Story", 2], ["Offer", 3]].map(([t, n], i) => L(`st s${n}`, `left:${x}px;top:${y + i * 88}px;width:${w}px`, pill(S, 0, 0, w, n, t))).join("");

// 1 Business Reels: hook boxes + reel covers band → notifications → camera into bottom panel with step pills → doc
scene("business-reels", "Business Reels", "Tela cheia, split e animação em tela cheia, trocando a cada corte.", {
  render: (S) => L("hk", `inset:0`, hookBoxes(S, ...h2(S), null, S.H * 0.06) + covers(S, S.H * 0.17)) + L("nf1", "inset:0", notifs(S, 80, S.H * 0.12, S.W - 160)) + L("bp", "inset:0", bottomPanel(S) + glow(S, S.W * 0.3, S.H * 0.4, 360)) + L("pl", "inset:0", stepPills(S, 150, S.H * 0.2, S.W - 300)) + L("dc", "inset:0", doc(S, 90, S.H * 0.12, S.W - 180, 440, "30-Day Content Plan", ["Days 1 to 10: Hook", "Days 11 to 20: Story", "Days 21 to 30: Offer"])),
  anim: (tl, el, cam) => { show(tl, el, ".hk", 0, 3.2); show(tl, el, ".nf1", 3.4, 6.6); seq(tl, el, ".nf1 .nf", 3.5); show(tl, el, ".bp", 7.0, 15); camToBottom(tl, cam, el, 7.0); show(tl, el, ".pl", 7.4, 10.4); seq(tl, el, ".pl .st", 7.6, 0.9); show(tl, el, ".dc", 10.8, 15); seq(tl, el, ".dc .dl", 11.2, 0.5); camBack(tl, cam, el, 14.6); } }, { camera: true });

// 2 Personal Reels: hook boxes → app notification → cream checklist (Hook/Story/Offer ticking) → green 30-day pad + "+8 enquiries"
scene("personal-reels", "Personal Reels", "Cortes rápidos, seu próprio B-roll e legenda de uma palavra.", {
  render: (S) => L("hk", "inset:0", hookBoxes(S, ...h2(S), null, S.H * 0.06)) + L("ap", "inset:0", abs(`left:${S.W / 2 - 40}px;top:${S.headTop - 120}px;width:80px;height:80px;border-radius:22px;background:#6f5cf6;box-shadow:0 10px 30px rgba(0,0,0,.4)`) + notif(S, S.W / 2 - 300, S.headTop - 20, 600, "YourApp", "3 new client enquiries this week")) + L("ck", "inset:0", cream(70, S.H * 0.08, S.W - 140, 520, `<div style="position:absolute;left:30px;top:24px;font:700 26px ${sans(S)}">Your content system</div>${[["Hook", 1], ["Story", 2], ["Offer", 3]].map(([t, n], i) => `<div class="ck${n}" style="position:absolute;left:24px;right:24px;top:${80 + i * 140}px;height:120px;border:2px solid #e3dccf;border-radius:16px"><span style="position:absolute;left:22px;top:16px;font:600 16px ${sans(S)};letter-spacing:.14em;color:#8a8478">STEP ${n}</span><span style="position:absolute;left:22px;top:44px;font:800 38px ${sans(S)}">${t}</span><i class="tick" style="position:absolute;right:22px;top:40px;width:44px;height:44px;border-radius:50%;background:#e3dccf;opacity:.6"></i></div>`).join("")}`)) + L("gp", "inset:0", abs(`left:${S.W / 2 - 300}px;top:${S.headTop + 140}px;width:600px;height:260px;border-radius:26px;background:#101010;border:1.5px solid ${LINE}`, grid30(S, 40, 36, 520, 40, 8, 10, 3, GREEN) + `<div class="gl" style="position:absolute;left:40px;bottom:18px;font:600 20px ${sans(S)};color:rgba(240,238,230,.6)">0 / 30 days</div>`) + L("pe", `left:${S.W / 2 - 120}px;top:${S.headTop + 420}px;width:240px;height:60px;border-radius:999px;background:${GREEN};color:#0c2a19;display:grid;place-items:center;font:800 28px ${sans(S)}`, "+8 enquiries")),
  anim: (tl, el) => { show(tl, el, ".hk", 0, 3.2); show(tl, el, ".ap", 3.4, 6.4); show(tl, el, ".ck", 6.6, 10.6); el.querySelectorAll(".ck .tick").forEach((t, i) => tl.to(t, { backgroundColor: CLAY, opacity: 1, duration: 0.3 }, 7.2 + i * 1.0)); show(tl, el, ".gp", 10.8, 15); fillGrid(tl, el, 11, 2.2, GREEN); const gl = el.querySelector(".gl"), o = { v: 0 }; tl.to(o, { v: 30, duration: 2.2, ease: "none", onUpdate: () => (gl.textContent = `${Math.round(o.v)} / 30 days`) }, 11); show(tl, el, ".pe", 13.6, 15); } });

// 3 Explainer Panel: dark canvas on top (tree diagram, "0 new clients"), presenter in the bottom panel, list 01/02/03, 30-day grid, +12 chart
